import type { ApolloServerPlugin } from '@apollo/server'
import { trace, context } from '@opentelemetry/api'
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-proto'
import { GrpcInstrumentation } from '@opentelemetry/instrumentation-grpc'
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http'
import { NodeSDK } from '@opentelemetry/sdk-node'

const endpoint = process.env.OTEL_EXPORTER_OTLP_TRACES_ENDPOINT

export const tracing = endpoint
  ? new NodeSDK({
      traceExporter: new OTLPTraceExporter({ url: endpoint }),
      metricReaders: [],
      logRecordProcessors: [],
      instrumentations: [
        new HttpInstrumentation({
          disableOutgoingRequestInstrumentation: true,
          ignoreIncomingRequestHook: (request) =>
            request.url === '/metrics' || request.method === 'OPTIONS',
        }),
        new GrpcInstrumentation(),
      ],
    })
  : undefined

tracing?.start()

export const tracingPlugin: ApolloServerPlugin = {
  async requestDidStart() {
    const span = trace.getSpan(context.active())
    return {
      async didResolveOperation({ operation, operationName }) {
        const type = operation.operation
        span?.updateName(operationName ? `${type} ${operationName}` : type)
        span?.setAttribute('graphql.operation.type', type)
        if (operationName) {
          span?.setAttribute('graphql.operation.name', operationName)
        }
      },
    }
  },
}

